class Pirate {
  constructor(name) {
    this.name = name;
    this.goldCoins = 0;
  }

  addGold(amount) {
    this.goldCoins += amount;
    return this.goldCoins;
  }

  removeGold(amount) {
    this.goldCoins = Math.max(0, this.goldCoins - amount);
    return this.goldCoins;
  }

  isRich() {
    return this.goldCoins >= 100;
  }

  greeting() {
    if (this.isRich()) return "Ahoy! I be " + this.name + ", the wealthiest pirate on the seas!";
    return "Ahoy! I be " + this.name + " and I have " + this.goldCoins + " gold coins!";
  }
}

