  addMenuItem(item) {
    this.menu.push(item);
  }

  placeOrder(itemNames) {
    const items = itemNames
      .map(name => this.menu.find(item => item.name === name))
      .filter(Boolean);
    this.orders.push(...items);
    return items.reduce((sum, item) => sum + item.price, 0);
