exercises.instructions:
JavaScript's `this` keyword changes based on how a function is called. Write functions that demonstrate each binding rule:

**methodContext()** — When called as an object method, `this` is the object:
```js
function methodContext() {
  const obj = {
    name: 'obj',
    getName() { return this.name; },
  };
  return obj.getName(); // 'obj'
}
```

**arrowContext()** — Arrow functions inherit `this` from enclosing scope:
```js
function arrowContext() {
  const obj = {
    name: 'obj',
    getNameArrow: () => this.name, // 'this' is outer scope, not obj
    getNameMethod() {
      const inner = () => this.name;
      return inner(); // arrow inherits from getNameMethod's this
    },
  };
  return [typeof obj.getNameArrow(), obj.getNameMethod()];
  // [undefined (or '' in browser), 'obj']
}
```

**explicitBinding()** — .call() and .bind() set `this`:
```js
function explicitBinding() {
  function greet() { return 'Hello, ' + this.name; }
  const person = { name: 'Alice' };
  const dog = { name: 'Rex' };
  const bound = greet.bind(person);
  return [greet.call(dog), bound()];
  // ['Hello, Rex', 'Hello, Alice']
}
```

**classContext()** — In a class, `this` is the instance:
```js
function classContext() {
  class Hero {
    constructor(name) { this.name = name; }
    announce() { return this.name + ' is here!'; }
  }
  const h = new Hero('Batman');
  return h.announce(); // 'Batman is here!'
}
```

