class Centaur {
  constructor(name, breed) {
    this.name = name;
    this.breed = breed;
    this.cranky = false;
    this.standing = true;
    this.actions = 0;
  }

  shoot() {
    if (this.cranky) return 'NO!';
    this.actions++;
    if (this.actions >= 3) this.cranky = true;
    return 'Twang!!!';
  }

  run() {
    if (this.cranky) return 'NO!';
    this.actions++;
    if (this.actions >= 3) this.cranky = true;
    return 'Clop clop clop clop!';
  }

  layDown() {
    this.standing = false;
  }

  standUp() {
    this.standing = true;
  }

  sleep() {
    if (this.standing) return 'NO!';
    this.actions = 0;
    this.cranky = false;
    return 'Zzz...';
  }

  drinkPotion() {
    this.cranky = false;
    return 'Aaah...';
  }
}

