class Medusa {
  constructor(name) {
    this.name = name;
    this.statues = [];
  }

  stare(person) {
    if (this.statues.length >= 3) {
      const freed = this.statues.shift();
      freed.stoned = false;
    }
    person.stoned = true;
    this.statues.push(person);
  }

  galesOfStone() {
    return this.statues.map(p => p.name);
  }
}

