class Human {
  constructor(name = 'Jane') {
    this.name = name;
    this.encounters = 0;
    this.knockedOut = false;
  }

  encounter() {
    this.encounters++;
  }

  noticesOgre() {
    return this.encounters % 3 === 0;
  }

  swingsAtOgre() {
    return 'pigswig!';
  }
}

class Ogre {
  constructor(name, home) {
    this.name = name;
    this.home = home;
    this.swpigsCount = 0;
  }

  encounter(human) {
    human.encounter();
    if (human.noticesOgre()) {
      human.swingsAtOgre();
      this.swpigsCount++;
      if (this.swpigsCount % 2 === 0) {
        human.knockedOut = true;
      }
    }
  }

  apologize(human) {
    human.knockedOut = false;
  }
}

